    out = [row[:] for row in grid]
    mark = [[False] * w for _ in range(h)]

    # Solid rectangles at least 5 cells tall and wide.
    for top in range(h):
        for bottom in range(top + 4, h):
            height = bottom - top + 1
            c = 0
            while c < w:
                color = grid[top][c]
                end = c + 1
                while end < w and grid[top][end] == color:
                    end += 1

                # Keep only columns that have this same color throughout.
                x = c
                while x < end:
                    if all(grid[r][x] == color for r in range(top, bottom + 1)):
                        x += 1
                        continue
                    x += 1

                # Find contiguous runs of columns uniform over the full height.
                x = c
                while x < end:
                    while x < end and not all(
                        grid[r][x] == color for r in range(top, bottom + 1)
                    ):
                        x += 1
                    start = x
                    while x < end and all(
                        grid[r][x] == color for r in range(top, bottom + 1)
                    ):
                        x += 1
                    if x - start >= 5:
                        for r in range(top, bottom + 1):
                            for y in range(start, x):
                                mark[r][y] = True
                c = end

    # Mark monochrome straight runs of five or more cells.
    for r in range(h):
        c = 0
        while c < w:
            end = c + 1
            while end < w and grid[r][end] == grid[r][c]:
                end += 1
            if end - c >= 5:
                for x in range(c, end):
                    mark[r][x] = True
            c = end

    for c in range(w):
        r = 0
        while r < h:
            end = r + 1
            while end < h and grid[end][c] == grid[r][c]:
                end += 1
            if end - r >= 5:
                for y in range(r, end):
                    mark[y][c] = True
            r = end

    for r in range(h):
        for c in range(w):
            if mark[r][c]:
                out[r][c] = 4
    return out
